import { spawnSync } from "node:child_process";
import { readFileSync, mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { Buffer } from "node:buffer";
import process from "node:process";
import console from "node:console";

const repairCommand = "pnpm -C 1-fe-host sec-ui:generate";

/** Compare source-generated bytes, including the shared Python consumer copy. */
export function assertCatalogArtifacts({ generatedPrompt, generatedSpec, frontendPrompt, frontendSpec, pythonPrompt }) {
  if (!generatedPrompt.toString().trim() || !generatedSpec.toString().trim()) throw new Error(`OpenUI generator produced empty artifacts. Run ${repairCommand}.`);
  const stale = [
    ["FE system-prompt.txt", generatedPrompt, frontendPrompt],
    ["FE system-prompt.spec.json", generatedSpec, frontendSpec],
    ["Python shared system-prompt.txt", generatedPrompt, pythonPrompt],
  ].filter(([, expected, actual]) => !Buffer.from(expected).equals(Buffer.from(actual))).map(([name]) => name);
  if (stale.length) throw new Error(`Stale OpenUI artifacts: ${stale.join(", ")}. Run ${repairCommand}.`);
}

export function checkOpenuiCatalog() {
  const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
  const temporary = mkdtempSync(join(tmpdir(), "reason-openui-catalog-"));
  try {
    const result = spawnSync(process.platform === "win32" ? "pnpm.cmd" : "pnpm", ["exec", "openui", "generate", "src/shared/ui/intelligent-ui/library.ts", "--out", join(temporary, "system-prompt.txt")], { cwd: root, encoding: "utf8", timeout: 120000, maxBuffer: 8 * 1024 * 1024 });
    if (result.error || result.status !== 0) throw new Error(`OpenUI source generation failed: ${result.error?.message ?? result.stderr ?? result.stdout}. Run ${repairCommand}.`);
    const generatedPrompt = readFileSync(join(temporary, "system-prompt.txt"));
    const generatedSpec = readFileSync(join(temporary, "system-prompt.spec.json"));
    assertCatalogArtifacts({
      generatedPrompt, generatedSpec,
      frontendPrompt: readFileSync(join(root, "src/shared/config/openui/system-prompt.txt")),
      frontendSpec: readFileSync(join(root, "src/shared/config/openui/system-prompt.spec.json")),
      pythonPrompt: readFileSync(join(root, "../3-langgraph-fast/src/graph/subgraphs/openui_output/generated/system-prompt.txt")),
    });
    console.log(`OpenUI catalog current: ${Object.keys(JSON.parse(generatedSpec).components).length} components; FE prompt/spec and Python mirror match.`);
  } finally { rmSync(temporary, { recursive: true, force: true }); }
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try { checkOpenuiCatalog(); }
  catch (error) { const message = error instanceof Error ? error.message : String(error); console.error(message.includes(repairCommand) ? message : `${message}\nRun ${repairCommand}.`); process.exitCode = 1; }
}
